<script setup lang="ts">
import { computed, ref } from 'vue'
const props=defineProps<{classified:any;recognition:any;files:any[];busy:boolean;frozen:boolean}>()
const emit=defineEmits<{role:[args:any];material:[args:any];retire:[args:any];export:[]}>()
const basis=ref(''),selected=ref(''),name=ref(''),model=ref(''),conductor=ref('')
const labels=computed<Record<string,string>>(()=>props.recognition?.role_labels||{})
const entries=computed<any[]>(()=>props.recognition?.entries||[])
const selectedEntry=computed(()=>entries.value.find(e=>e.solidified_id===selected.value))
function links(path:string){return entries.value.filter(e=>e.files.some((f:any)=>f.storage_path===path))}
function edit(id:string){selected.value=id;name.value='';model.value='';conductor.value=''}
const fieldLabels:Record<string,string>={model:'招标文件写的型号',conductor:'招标文件写的导体材质',specification:'规格',voltage:'电压',voltage_annotations:'电压说明'}
function values(m:any,key:string):string[]{return [...new Set<string>((m.composition_history||[]).flatMap((h:any)=>(h.parameters?.[key]||[]).map((v:any)=>typeof v==='string'?v:v?.value)).filter((v:any)=>typeof v==='string'&&v.trim()))]}
function fields(m:any){const keys=[...new Set<string>((m.composition_history||[]).flatMap((h:any)=>Object.keys(h.parameters||{})))];return keys.filter(k=>fieldLabels[k]||/[\u4e00-\u9fff]/.test(k)).map(k=>({key:k,label:fieldLabels[k]||k,value:values(m,k).join('；')})).filter(f=>f.value)}
function explanation(m:any){const issues=(m.composition_history||[]).flatMap((h:any)=>h.issues||[]);const conflict=issues.find((i:any)=>i.conflict&&i.model_value&&i.table_value);return conflict?`型号通常代表${conflict.model_value}，但导体栏写的是${conflict.table_value}，二者不一致，会影响最终物料名称，请按实际产品确认。`:m.needs_confirmation?'资料中的名称或参数尚未确认，可能影响后续物料匹配，请核对后填写最终名称和依据。':'人工确认结果已采用，之前的差异保留在技术依据中。'}
</script>
<template><section class="recognition-panel"><h2>角色与物料识别结果</h2><p class="status">本轮跳过全量回归，仅做定向验证。</p><p>已识别 {{files.length}} 个文件/容器，{{recognition?.id_count||0}} 个固化ID；{{recognition?.pending_ids?.length||0}} 个物料待确认。</p><div class="counts"><span v-for="(count,role) in recognition?.role_counts" :key="role">{{labels[String(role)]||role}} {{count}}</span></div><label>本次纠正依据 <input v-model="basis" placeholder="填写核对过的清单、澄清文件或书面结论"></label><p>确认人由当前登录账号记录；不预选人工结论。已汇聚SSOT的任务显示冻结结果，请在新任务中调整上游识别。</p>
<div class="scroll"><table><thead><tr><th>来源文件</th><th>角色与依据</th><th>固化ID / 识别名称 / 来源</th><th>人工纠正</th></tr></thead><tbody><tr v-for="f in files" :key="f.storage_path"><td>{{f.logical_path}}</td><td>{{labels[f.role]||f.role}}<small>{{f.role_evidence?.join('；')}}</small><small v-if="f.manual_override">人工：{{f.manual_override.actor}} · {{f.manual_override.reason}}</small></td><td><div v-for="m in links(f.storage_path)" :key="m.solidified_id">{{m.solidified_id}}<br>{{m.material_name||'待确认，尚无可靠名称'}}<small>{{m.needs_confirmation?'待确认':'已具备名称依据'}}</small></div><span v-if="!links(f.storage_path).length">无物料关联</span></td><td><select :value="''" :disabled="busy||frozen" aria-label="人工文件角色" @change="emit('role',{storage_path:f.storage_path,role:($event.target as HTMLSelectElement).value,basis})"><option value="" disabled>选择纠正角色</option><option v-for="(label,key) in labels" v-show="key!=='pending'" :key="key" :value="key" :disabled="key==='pending'">{{label}}</option></select></td></tr></tbody></table></div>
<h3>物料核对</h3><article v-for="m in entries" :key="m.solidified_id" :data-material-id="m.solidified_id"><h4>{{m.solidified_id}} · {{m.needs_confirmation?'待确认':m.source_type==='manual'?'已人工确认':'已有可追溯名称'}}</h4><p><strong>物料名称：</strong>{{m.material_name||'待确认'}}</p><p v-for="f in fields(m)" :key="f.key"><strong>{{f.label}}：</strong>{{f.value}}</p><p v-if="m.needs_confirmation||m.historical_conflict" class="warning">{{explanation(m)}}</p><details><summary>查看来源与技术依据</summary><pre>{{JSON.stringify(m,null,2)}}</pre></details><button :disabled="busy||frozen" @click="edit(m.solidified_id)">核对此物料</button></article>
<section v-if="selectedEntry" class="editor"><h3>人工裁决：{{selected}}</h3><p v-if="selectedEntry.needs_confirmation||selectedEntry.historical_conflict" class="warning">{{explanation(selectedEntry)}}</p><details><summary>查看来源与技术依据</summary><pre>{{JSON.stringify(selectedEntry,null,2)}}</pre><div v-for="s in selectedEntry.sources.filter((x:any)=>x.record_id)" :key="s.record_id"><span>{{s.name||'人工来源'}}</span><button :disabled="busy||frozen||s.active===false" @click="emit('retire',{record_id:s.record_id,basis})">停用此来源并保留历史</button></div></details><label>最终物料名称 <input v-model="name" placeholder="填写有依据的完整物料名称"></label><label>最终型号 <input list="material-model-options" v-model="model" placeholder="如需裁决型号，请人工填写"></label><label>实际确认导体 <input list="material-conductor-options" v-model="conductor" placeholder="存在合成/导体冲突时必填"></label><datalist id="material-model-options"><option v-for="v in values(selectedEntry,'model')" :key="v" :value="v" /></datalist><datalist id="material-conductor-options"><option v-for="v in values(selectedEntry,'conductor')" :key="v" :value="v" /></datalist><label>确认依据 <input v-model="basis" placeholder="填写核对过的文件或书面结论"></label><p>名称、型号、材质均不自动填入。确认依据使用上方“本次纠正依据”。与型号代号矛盾的输入将被拒绝。</p><button :disabled="busy||frozen" @click="emit('material',{solidified_id:selected,name,model,conductor,basis})">确认此物料</button><button :disabled="busy" @click="selected=''">暂不处理</button></section>
<p>物料核对进度：{{recognition?.ssot_ready?'名称依据已齐全，可校验导出':'仍有待确认项，不导出虚假的最终映射'}}</p><button :disabled="busy||!recognition?.ssot_ready" @click="emit('export')">校验并整理确认结果</button><details v-if="classified.material_source_ledger?.length"><summary>补齐与人工来源账本</summary><pre>{{JSON.stringify(classified.material_source_ledger,null,2)}}</pre></details></section></template>
<style scoped>.recognition-panel{border:1px solid #d5dbe4;border-radius:10px;padding:20px;margin:20px 0;background:var(--card,#fff)}h2{font-size:20px}h3{margin-top:20px;font-size:18px}h4{font-weight:600}.counts{display:flex;flex-wrap:wrap;gap:12px;margin:12px 0}.status{background:#fff4cf;padding:10px}input,select,button{border:1px solid #b5c0ce;border-radius:5px;padding:8px;margin:5px}button{background:#164b83;color:white}button:disabled{opacity:.45}small{display:block;overflow-wrap:anywhere;color:#64748b}.scroll{max-height:55vh;overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:10px;border:1px solid #d5dbe4;text-align:left;vertical-align:top}article{padding:16px 0;border-bottom:1px solid #d5dbe4}.evidence{display:grid;grid-template-columns:1fr 1fr;gap:14px}.evidence>div,.evidence>details{min-width:0;background:#f6f8fb;padding:10px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:350px;overflow:auto;font-size:13px}.warning{color:#b45309}.editor{border:2px solid #164b83;padding:16px}label{display:inline-block} @media(max-width:800px){.evidence{grid-template-columns:1fr}}</style>

